"""Generate paper numbers exclusively from complete, approved full-row records."""
import collections
import csv
import hashlib
import json
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
from scipy.stats import pearsonr, rankdata, spearmanr, t
from report_gptj_pythia_diagnosis import scalar_rho

ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT/"results/all_models_gender_original_continents"
NEWLINE = ROOT/"results/gptj_pythia_full_row_diagnosis"
OUT = ROOT/"results/paper_full_evaluation"
PAPER = ROOT.parent/"paper"
TEX = PAPER/"generated/full_evaluation"
LABELS = {"olmo3_7b":"OLMo 3 7B", "gptj":"GPT-J 6B", "pythia6_9b":"Pythia 6.9B", "mistral7b":"Mistral 7B", "gemma2_9b":"Gemma 2 9B", "qwen3_8b_base":"Qwen3 8B Base", "qwen3_8_27b":"Qwen3.8 27B"}
NEWLINE_MODELS = {"gptj", "pythia6_9b", "qwen3_8b_base", "qwen3_8_27b"}
plt.rcParams.update({"pdf.fonttype":42,"ps.fonttype":42})


def read(p): return json.loads(p.read_text())
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def esc(s): return s.replace("_", r"\_")
def write(name, text): (TEX/(name+".tex")).write_text("% Generated by code/scripts/build_full_evaluation_paper.py.\n"+text+"\n")
def rho(x, y):
    s = spearmanr(x, y)
    assert abs(float(s.statistic)-scalar_rho(list(x),list(y))) < 1e-12
    return dict(rho=float(s.statistic), p=float(s.pvalue), n=len(x))
def ptex(p):
    if p >= .001: return f"{p:.3f}"
    a, b = f"{p:.2e}".split("e")
    return rf"{a}\times10^{{{int(b)}}}"
def partial(x, y, *controls):
    a, b = rankdata(x), rankdata(y)
    z = np.column_stack([np.ones(len(a))]+[rankdata(c) for c in controls])
    a -= z@np.linalg.lstsq(z,a,rcond=None)[0]
    b -= z@np.linalg.lstsq(z,b,rcond=None)[0]
    r = float(pearsonr(a,b).statistic)
    df = len(a)-len(controls)-2
    return dict(rho=r, p=float(2*t.sf(abs(r)*np.sqrt(df/(1-r*r)),df)), n=len(a), controls=len(controls))
def table(caption, label, columns, heading, rows, foot=""):
    return "\n".join([r"\begin{table}[t]",r"\centering\small",r"\caption{"+caption+"}",r"\label{"+label+"}",r"\begin{tabular}{@{}"+columns+"@{}}",r"\toprule",heading+r" \\",r"\midrule",*[row+r" \\" for row in rows],r"\bottomrule",r"\end{tabular}",r"\par\smallskip\begin{minipage}{\linewidth}\footnotesize "+foot+r"\end{minipage}" if foot else "",r"\end{table}"])


def main():
    TEX.mkdir(parents=True,exist_ok=True)
    OUT.mkdir(parents=True,exist_ok=True)
    records, models, provenance, baseline_complete = {}, {}, {}, True
    for name in LABELS:
        manifest = read(BASE/name/"manifest.json")
        assert len(manifest["dataset"]) == 28
        entries = []
        for rel, plan in sorted(manifest["dataset"].items()):
            fp = BASE/name/"measurements"/(rel+".json")
            lp = (NEWLINE if name in ["gptj","pythia6_9b"] else BASE)/name/"measurements"/(rel+".json")
            f, lens = read(fp), read(lp)["lens"]
            data_path = ROOT/"data/relations"/(rel+".json")
            data = read(data_path)
            assert sha(data_path) == f["data_sha256"] == plan["data_sha256"]
            assert f["n_original"] == lens["n"] == len(data["samples"])
            assert collections.Counter((r["subject"],r["object"]) for r in lens["rows"]) == collections.Counter((r["subject"],r["object"]) for r in data["samples"])
            assert len(lens["rows"]) == len(f["faithfulness"]["rows"]) == lens["n"]
            score = -float(np.median(np.log10(np.array([r["rank_diff"] for r in lens["rows"]])+1)))
            assert abs(score+lens["agg"]["diff"]["median_lograng"]) < 1e-12
            baseline_path = OUT/name/"measurements"/(rel+".json")
            baseline = read(baseline_path) if baseline_path.exists() else None
            if baseline:
                assert baseline["lre_sha256"] == sha(fp)
                assert baseline["approved_lens_sha256"] == sha(lp)
                assert baseline["n_original"] == lens["n"]
                assert baseline["gender_alternatives_all_readouts"]
                assert baseline["lens"]["neutral_prompt"] == lens["neutral_prompt"]
                for a,b in zip(baseline["lens"]["rows"],lens["rows"],strict=True):
                    for key in ["subject","object","model_top1_id","n_references"]: assert a[key] == b[key]
                provenance[str(baseline_path.relative_to(ROOT))] = sha(baseline_path)
            else: baseline_complete = False
            entries.append(dict(relation=rel,n=lens["n"],score=score,faith=f["faithfulness"]["best_faith"],frozen=f["faithfulness"]["fixed_faith"],excluded=f["date_audit"]["excluded"],k=len(data["samples"])/len({r["object"] for r in data["samples"]}),data=data,lens=lens,faith_record=f,baseline=baseline))
            provenance[str(fp.relative_to(ROOT))] = sha(fp)
            provenance[str(lp.relative_to(ROOT))] = sha(lp)
        assert sum(e["n"] for e in entries) == 9747
        eligible = [e for e in entries if not e["excluded"]]
        models[name] = dict(label=LABELS[name],newline=name in NEWLINE_MODELS,n_relations=len(eligible),n_scored_rows=sum(e["n"] for e in eligible),primary=rho([e["score"] for e in eligible],[e["faith"] for e in eligible]),frozen=rho([e["score"] for e in eligible],[e["frozen"] for e in eligible]),all28=rho([e["score"] for e in entries],[e["faith"] for e in entries]),all28_frozen=rho([e["score"] for e in entries],[e["frozen"] for e in entries]),excluded=[e["relation"] for e in entries if e["excluded"]],lens_layer=manifest["lens_layer"],lre_layers=manifest["layers"])
        records[name] = entries
    olmo = records["olmo3_7b"]
    x,y,k = [[e[field] for e in olmo] for field in ["score","faith","k"]]
    controls = dict(cardinality_faith=rho(k,y),cardinality_lens=rho(k,x),partial_cardinality=partial(x,y,k))
    if all(e["baseline"] for e in olmo):
        priors = [float(np.mean([r["answer_prior"] for r in e["baseline"]["lens"]["rows"]])) for e in olmo]
        controls.update(prior_faith=rho(priors,y),prior_lens=rho(priors,x),partial_prior=partial(x,y,priors),partial_both=partial(x,y,k,priors))
    fit = np.polyfit(x,y,1)
    for e in olmo:e["residual"] = float(e["faith"]-np.polyval(fit,e["score"]))
    facts = []
    for e in olmo:
        by_pair = collections.defaultdict(collections.deque)
        faith_rows = e["faith_record"]["faithfulness"]["rows"]
        if e["relation"] == "name_gender" and any("rank" not in r for r in faith_rows):
            restored_path = OUT/"olmo_gender_lre_ranks.json"
            restored = read(restored_path)
            assert restored["source_sha256"] == sha(BASE/"olmo3_7b/measurements/name_gender.json")
            assert restored["best_key"] == e["faith_record"]["faithfulness"]["best_key"]
            for a,b in zip(restored["rows"],faith_rows,strict=True):
                for key in ["subject","object","model_top1_id","hit"]:assert a[key] == b[key]
            faith_rows = restored["rows"]
            provenance[str(restored_path.relative_to(ROOT))] = sha(restored_path)
        for r in faith_rows: by_pair[r["subject"],r["object"]].append(r)
        a,b,mismatch = [],[],0
        for r in e["lens"]["rows"]:
            f = by_pair[r["subject"],r["object"]].popleft()
            a.append(r["rank_diff"]);b.append(f["rank"]);mismatch += r["model_top1_id"] != f["model_top1_id"]
        assert not any(by_pair.values())
        rr = rho(a,b) if len(set(a)) > 1 and len(set(b)) > 1 else dict(rho=None,p=None,n=len(a))
        facts.append(dict(relation=e["relation"],**rr,target_disagreements=mismatch))
    # Restore duplicates when joining the corpus's unique fact strings.
    corpus_path = ROOT/"generated/corpus_conditionals/all_stages.facts.csv"
    assert read(ROOT/"generated/corpus_conditionals/progress.json")["state"] == "complete"
    corpus_rows = list(csv.DictReader(corpus_path.open()))
    corpus = {(r["relation"],r["subject"],r["object"]):r for r in corpus_rows}
    assert len(corpus) == len(corpus_rows)
    features = collections.defaultdict(list)
    unobserved = 0
    for e in olmo:
        raw = [corpus[e["relation"],r["subject"],r["object"]] for r in e["data"]["samples"]]
        cs,co,cso = [np.array([int(r[key]) for r in raw],dtype=float) for key in ["subject_count","object_count","cooccurrence"]]
        unobserved += int(((cs == 0)|(co == 0)).sum())
        forward = np.divide(cso,cs,out=np.zeros_like(cso),where=cs>0)
        reverse = np.divide(cso,co,out=np.zeros_like(cso),where=co>0)
        vals = dict(subject=cs.mean(),object=co.mean(),joint=cso.mean(),mean_log_joint=np.log1p(cso).mean(),log_mean_joint=np.log1p(cso.mean()),forward=forward.mean(),reverse=reverse.mean(),direction=(forward-reverse).mean(),micro_forward=cso.sum()/cs.sum(),micro_reverse=cso.sum()/co.sum())
        for key,value in vals.items():features[key].append(float(value))
    corpus_correlations = {key:rho(values,y) for key,values in features.items()}
    provenance[str(corpus_path.relative_to(ROOT))] = sha(corpus_path)
    generate_tex(models,olmo,controls,facts,corpus_correlations,unobserved,records,baseline_complete)
    plot(olmo,models)
    summary = dict(models=models,controls=controls,fact_correlations=facts,corpus_correlations=corpus_correlations,corpus_rows_with_unobserved_marginal=unobserved,neural_baselines_complete=baseline_complete,attribute_baselines_complete=(OUT/"attribute_rates.json").exists(),source_sha256=provenance)
    (OUT/"paper_statistics.json").write_text(json.dumps(summary,indent=2,allow_nan=False)+"\n")
    rows=[]
    for name,m in models.items():
        for variant in ['primary','frozen','all28','all28_frozen']:
            rows.append(dict(family='differential',model=name,feature=variant,**m[variant]))
    if baseline_complete:
        for name,features in read(OUT/'baseline_correlations.json').items():
            for key,values in features.items():rows.append(dict(family='baseline',model=name,feature=key,**values))
    for key,values in corpus_correlations.items():rows.append(dict(family='corpus',model='olmo3_7b',feature=key,**values))
    with (OUT/'correlations.csv').open('w') as f:
        writer=csv.DictWriter(f,fieldnames=['family','model','feature','rho','p','n']);writer.writeheader();writer.writerows(rows)
    relation_rows=[]
    for name,entries in records.items():
        for e in entries:
            row=dict(model=name,relation=e['relation'],n_rows=e['n'],primary_scored=not e['excluded'],newline=models[name]['newline'],faithfulness=e['faith'],frozen_faithfulness=e['frozen'],differential_score=e['score'])
            for kind in ['raw_jacobian','logit_lens','differential_logit_lens','lre']:
                row[kind+'_score']=-e['baseline']['lens']['agg'][kind]['median_lograng'] if e['baseline'] else None
            relation_rows.append(row)
    with (OUT/'relation_scores.csv').open('w') as f:
        writer=csv.DictWriter(f,fieldnames=list(relation_rows[0]));writer.writeheader();writer.writerows(relation_rows)
    lines=['# Current full-evaluation paper results','',f"Complete: **{baseline_complete and summary['attribute_baselines_complete']}**.",'',
           'Original 28 relations; every one of 9,747 rows/model measured, including demonstrations/references and duplicates. Gender alternatives enabled; original continent references. Primary year exclusions leave 26 relations and 9,709 scored rows in Mistral, Gemma and both Qwen models. LRE hyperparameters are selected on the full evaluation; frozen-parameter and all-28 sensitivities are supplied. These are in-sample results.','',
           '| Model | Relations | Spearman ρ | Leading newline |','|---|---:|---:|:---:|']
    for name,m in models.items():lines.append(f"| {m['label']} | {m['n_relations']} | {m['primary']['rho']:.6f} | {'Yes' if m['newline'] else 'No'} |")
    lines += ['', 'The newline models are GPT-J, Pythia and both Qwen models; the appendix documents first-position norm diagnostics. Approved differential ranks and all LRE outcomes are reused. Missing raw Jacobian, logit-lens, differential-logit-lens and attribute baselines are measured on the same full evaluation, with gender alternatives applied consistently to target-rank readouts.', '',
              'Attribute rate explicitly assigns zero overlap to rows whose filtered top-50 prediction set is empty. Corpus conditional features explicitly use zero for an unobserved conditioning marginal (207 dataset rows have at least one unobserved marginal). Neither convention drops a row. These extensions are documented in the paper.', '',
              'The paper uses CEL (contrastive/differential lens) as the primary readout; NEL is a separate raw-Jacobian baseline. Earlier shared-split/capped results and incompatible small-cohort numerical sections are preserved in the dated paper archive and excluded from compilation.', '',
              'Artifacts: [all correlations](correlations.csv), [statistics/provenance](paper_statistics.json), [PDF](../../../paper/lens.pdf), [paper guide](../../../paper/README.md), and `paper_release_audit.json` (created only after all measurements and PDF checks pass).']
    (OUT/'README.md').write_text('\n'.join(lines)+'\n')
    print(json.dumps(dict(neural_baselines_complete=baseline_complete,models={n:m["primary"] for n,m in models.items()},controls=controls),indent=2))


def generate_tex(models,olmo,controls,facts,corpus,unobserved,records,baseline_complete):
    headline = models["olmo3_7b"]["primary"]
    macros = [rf"\newcommand{{\headlinenumber}}{{{headline['rho']:.3f}}}",rf"\newcommand{{\headlinep}}{{{ptex(headline['p'])}}}"]
    for key,rel in [("capitalfaith","country_capital_city"),("fatherfaith","person_father")]:
        e = next(e for e in olmo if e["relation"] == rel)
        macros.append(rf"\newcommand{{\{key}}}{{{100*e['faith']:.1f}\%}}")
    write("macros","\n".join(macros))
    model_rows, sensitivity_rows, parameter_rows = [],[],[]
    for name,m in models.items():
        label = m["label"]+(r"$^{\dagger}$" if m["newline"] else "")
        model_rows.append(f"{label} & {m['n_relations']} & {m['n_scored_rows']:,} & ${m['primary']['rho']:.4f}$ & ${ptex(m['primary']['p'])}$")
        sensitivity_rows.append(f"{label} & {m['n_relations']} & ${m['primary']['rho']:.4f}$ & ${m['frozen']['rho']:.4f}$ & ${m['all28']['rho']:.4f}$")
        parameter_rows.append(f"{label} & {m['lens_layer']} & "+", ".join(map(str,m['lre_layers'])))
    foot = r"$^{\dagger}$Leading newline in the neutral lens prompt to address high first-position activation norms. All eligible rows, including demonstration/reference rows, are evaluated. Models with 26 scored relations exclude the two year relations whose first answer token is the standalone digit 1; all 28 relations were measured. Gender alternatives are enabled; continent references use the original seeded selection."
    write("models",table("Full-evaluation contrastive/differential Jacobian lens correlations with LRE faithfulness. LRE layer and scaling are selected on the full evaluation grid.","tab:full-models","lrrrr",r"Model & Relations & Scored rows & Spearman $\rho$ & $p$",model_rows,foot))
    write("sensitivity",table("Correlation sensitivity to LRE parameter selection and year scoring. All columns use complete relation evaluations.","tab:full-sensitivity","lrrrr",r"Model & Primary $n$ & Selected & Frozen & All 28",sensitivity_rows,r"Selected: best layer/scaling on full evaluation. Frozen: original layer/scaling retained, outcomes evaluated on all rows. All 28: both year relations included as a tokenization sensitivity, using selected LRE parameters. $^{\dagger}$Newline models as in Table~\ref{tab:full-models}."))
    write("parameters",table("Fixed lens layers and LRE candidate layers (one-based block outputs).","tab:full-parameters","lrl",r"Model & Lens layer & LRE candidate layers",parameter_rows,r"Every LRE layer is crossed with $\beta\in\{0.5,1,1.5,2,3,5\}$. The lens layer is fixed across relations within each model. $^{\dagger}$Leading newline."))
    relrows = [f"{esc(e['relation'])} & {e['n']} & {e['k']:.1f} & {e['faith']:.4f} & ${e['score']:.4f}$" for e in sorted(olmo,key=lambda e:-e['faith'])]
    write("relations_olmo",table("OLMo full-evaluation results for all 28 original relations. $k$ is rows per distinct full object; $A_r$ is the contrastive lens score.","tab:relations","lrrrr",r"Relation & Rows & $k$ & Faithfulness & $A_r$",relrows,r"Every original row and duplicate is retained. Eight demonstration and eight reference rows are also part of the evaluation. Both year relations are retained for OLMo after token-boundary auditing."))
    text = rf"Across all 28 OLMo relations, cardinality has Spearman $\rho={controls['cardinality_faith']['rho']:.3f}$ with faithfulness ($p={ptex(controls['cardinality_faith']['p'])}$) and $\rho={controls['cardinality_lens']['rho']:.3f}$ with the lens score. The partial Spearman correlation controlling for cardinality is ${controls['partial_cardinality']['rho']:.3f}$ ($p={ptex(controls['partial_cardinality']['p'])}$)."
    if "partial_both" in controls:
        text += "\n\n"+rf"Answer-token prior has Spearman $\rho={controls['prior_faith']['rho']:.3f}$ with faithfulness and $\rho={controls['prior_lens']['rho']:.3f}$ with the lens score. Controlling for this prior gives $\rho={controls['partial_prior']['rho']:.3f}$; controlling for both prior and cardinality gives $\rho={controls['partial_both']['rho']:.3f}$ ($p={ptex(controls['partial_both']['p'])}$). The prior is the mean log probability of each evaluation target under ten neutral contexts, averaged over every original row."
    write("controls",text)
    positive = sorted(olmo,key=lambda e:-e["residual"])[:3]
    negative = sorted(olmo,key=lambda e:e["residual"])[:3]
    def examples(entries):return ", ".join(rf"\textsc{{{esc(e['relation'])}}} (${e['residual']:+.3f}$, $k={e['k']:.1f}$)" for e in entries)
    write("residuals","The largest positive residuals are "+examples(positive)+". The largest negative residuals are "+examples(negative)+". These residuals are recomputed from the least-squares fit to the full-evaluation points; they are measured in faithfulness units.")
    defined = [f for f in facts if f["rho"] is not None]
    undefined = [f["relation"] for f in facts if f["rho"] is None]
    facttext = rf"We join all 9,747 OLMo evaluation rows by subject and object, retaining duplicate occurrences, and correlate the two answer-token ranks within each relation. Correlations are defined for {len(defined)} of 28 relations, ranging from ${min(f['rho'] for f in defined):.3f}$ to ${max(f['rho'] for f in defined):.3f}$, with median ${np.median([f['rho'] for f in defined]):.3f}$ among defined relations."
    if undefined:facttext += " Constant ranks make the statistic undefined for "+", ".join(rf"\textsc{{{esc(r)}}}" for r in undefined)+"; their rows are retained in every other analysis."
    facttext += rf" The two methods use different demonstration contexts, whose target tokens disagree on {sum(f['target_disagreements'] for f in facts):,} of these rows. These within-relation associations therefore combine readout differences with context sensitivity; they do not compare an identical target under matched contexts."
    write("fact_summary",facttext)
    factrows = [f"{esc(f['relation'])} & {f['n']} & "+(f"${f['rho']:.3f}$" if f['rho'] is not None else "undefined")+f" & {f['target_disagreements']}" for f in facts]
    write("fact_table",table("Full-row OLMo rank correlations within each relation, with target-context disagreement counts.","tab:full-facts","lrrr",r"Relation & Rows & Spearman $\rho$ & Different targets",factrows))
    corpus_labels = {"subject":r"Mean subject document count", "object":r"Mean object document count", "joint":r"Mean joint document count", "mean_log_joint":r"Mean $\log(1+c_{so})$", "log_mean_joint":r"$\log(1+\mathrm{mean}(c_{so}))$", "forward":r"Mean $P(o\mid s)$", "reverse":r"Mean $P(s\mid o)$", "direction":r"Mean $P(o\mid s)-P(s\mid o)$", "micro_forward":r"Micro $P(o\mid s)$", "micro_reverse":r"Micro $P(s\mid o)$"}
    write("corpus",table("OLMo corpus-frequency baselines, reaggregated over all 9,747 original rows and correlated with full-evaluation LRE faithfulness across all 28 relations.","tab:full-corpus","lrr",r"Feature & Spearman $\rho$ & $p$",[f"{corpus_labels[k]} & ${c['rho']:.4f}$ & ${ptex(c['p'])}$" for k,c in corpus.items()],rf"Counts use binary document presence across the three saved OLMo training-mix scans. Duplicate dataset rows receive their original multiplicity. An unobserved conditioning marginal gives a conditional feature of zero, rather than dropping the row; {unobserved} rows have at least one unobserved marginal. Micro conditionals divide summed joint counts by summed marginal counts. Values are exploratory and $p$-values are unadjusted."))
    changes = read(NEWLINE/"summary.json")
    change_rows = []
    for name in ["gptj","pythia6_9b"]:
        vals = {(r['variant'],r['lre_axis']):r['spearman_rho'] for r in changes['correlations'] if r['model'] == name}
        diag = changes['evidence'][name]['subject_norms_by_original_position']['position_zero']
        change_rows.append(f"{LABELS[name]} & {vals['original','faithfulness']:.4f} & {vals['newline','faithfulness']:.4f} & {diag['original_median']:.0f} & {diag['newline_median']:.0f}")
    write("newline",table("Full-evaluation newline ablation for the two additional models. All 28 relations, 9,747 rows, LRE results and target tokens are fixed.","tab:full-newline","lrrrr",r"Model & Original $\rho$ & Newline $\rho$ & Original norm & Newline norm",change_rows,r"Norm columns give median subject-state norms for rows whose subject endpoint was at token position zero before adding the newline (142 GPT-J rows; 83 Pythia rows). The newline shifts the subject away from position zero without changing its content token IDs. Qwen3 8B Base and Qwen3.8 27B retain the previously adopted newline correction; their current full-evaluation correlations are in Table~\ref{tab:full-models}."))
    if baseline_complete:
        kinds = ["raw_jacobian","logit_lens","differential_logit_lens","lre"]
        rows, data, coverage = [],{},[]
        wiki_path = OUT/"attribute_rates.json"
        wiki = read(wiki_path) if wiki_path.exists() else None
        for name,m in models.items():
            eligible = [e for e in records[name] if not e['excluded']]
            data[name] = {}
            for kind in kinds:
                scores = []
                for e in eligible:
                    lens = e['baseline']['lens']
                    score = -float(np.median(np.log10(np.array([r['rank_'+kind] for r in lens['rows']])+1)))
                    assert abs(score+lens['agg'][kind]['median_lograng']) < 1e-12
                    scores.append(score)
                data[name][kind] = rho(scores,[e['faith'] for e in eligible])
            attr = None
            if wiki:
                values = [wiki[name]['relations'][e['relation']]['mean_zero_extended'] for e in eligible]
                attr = rho(values,[e['faith'] for e in eligible]);data[name]['attribute_rate'] = attr
            label = m['label']+(r"$^{\dagger}$" if m['newline'] else "")
            if wiki:
                undefined = sum(wiki[name]['relations'][e['relation']]['undefined_original'] for e in eligible)
                coverage.append(f"{label} & {m['n_scored_rows']:,} & {undefined:,}")
            rows.append(label+f" & {m['primary']['rho']:.4f} & {data[name]['raw_jacobian']['rho']:.4f} & {data[name]['logit_lens']['rho']:.4f} & {data[name]['differential_logit_lens']['rho']:.4f} & "+(f"{attr['rho']:.4f}" if attr else "pending"))
        write("baselines",table("Neural and Wikipedia attribute baselines using the same full evaluations, targets, reference sets, layer, prompt correction, gender alternatives and year rule as the contrastive lens.","tab:full-baselines","lrrrrr",r"Model & CEL & NEL & Logit & Diff. logit & Attribute",rows,r"CEL: contrastive/differential Jacobian lens; NEL: raw/noncontrastive Jacobian lens. Higher scores mean better target ranks. $^{\dagger}$Leading newline. Attribute overlap is zero when no top-50 predictions survive the published length/stopword filter; no evaluation rows are dropped. These are point estimates, not evidence of significant differences between readouts."))
        affine_rows = [m['label']+(r"$^{\dagger}$" if m['newline'] else "")+f" & {data[name]['lre']['rho']:.4f}" for name,m in models.items()]
        write("affine",table(r"Anchored neutral Jacobian readout at fixed $\beta=1$, under the same full evaluation and scoring corrections.","tab:full-affine","lr",r"Model & Spearman $\rho$",affine_rows,r"The readout averages $f(s_i)+J_i(s-s_i)$ under the neutral prompt. The LRE outcome still uses its selected relation-context layer and scaling. No cross-relation tuning of the neutral readout is performed."))
        (OUT/"baseline_correlations.json").write_text(json.dumps(data,indent=2)+"\n")
        if wiki:write("attribute_coverage",table("Attribute-rate coverage under the full primary evaluation.","tab:attribute-coverage","lrr",r"Model & Scored rows & Empty filtered predictions",coverage,r"Rows with no surviving top-50 prediction are assigned zero overlap in the reported extension. No original row is removed for an undefined attribute rate."))


def plot(olmo,models):
    fig,ax = plt.subplots(figsize=(8.4,5.2),constrained_layout=True)
    for e in olmo:
        ax.scatter(e["score"],e["faith"],marker="^" if "year" in e["relation"] else "o",s=32,color="#2563a6")
    labels = {e["relation"] for e in sorted(olmo,key=lambda e:e["residual"])[:3]+sorted(olmo,key=lambda e:-e["residual"])[:3]}
    labels |= {"country_capital_city","person_mother","person_father","name_gender","landmark_on_continent","person_native_language","company_ceo"}
    for e in olmo:
        if e["relation"] in labels:
            right = e["score"] > -1.2
            offset = {"person_native_language":(-70,24), "country_capital_city":(-12,-22), "landmark_on_continent":(8,-19), "company_ceo":(6,-15)}.get(e["relation"],(-5 if right else 5,7))
            ax.annotate(e["relation"],(e["score"],e["faith"]),xytext=offset,ha="right" if right else "left",textcoords="offset points",fontsize=7,bbox=dict(facecolor="white",edgecolor="none",alpha=.85,pad=1),arrowprops=dict(arrowstyle="-",color="#777777",lw=.5))
    ax.set(xlabel="Contrastive entity lens score (higher is better)",ylabel="LRE faithfulness",ylim=(-.04,1.08))
    ax.set_title(f"OLMo 3 7B · 28 relations · all 9,747 rows · Spearman ρ = {models['olmo3_7b']['primary']['rho']:.4f}")
    ax.grid(alpha=.2)
    fig.savefig(PAPER/"fig_full_evaluation.pdf")
    fig.savefig(OUT/"fig_full_evaluation.png",dpi=180)
    plt.close(fig)


if __name__ == "__main__":main()
